import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion, useSpring, useMotionValue, animate } from "framer-motion";
import { cn } from "@/lib/utils";

export interface BeamConnection {
  id?: string;
  /** Source node id (must exist in `BeamNode.id` on a child). */
  from: string;
  /** Target node id. */
  to: string;
  /** Override beam color (CSS color string). */
  color?: string;
  /** Curvature 0..1 — how much the cubic bezier bows. */
  curvature?: number;
  /** Beam pulse interval in ms. */
  interval?: number;
  /** Initial delay before the first pulse, in ms. */
  delay?: number;
  /** Pulse travel duration in ms. */
  duration?: number;
}

export interface InteractiveBeamConnectionsProps {
  connections: BeamConnection[];
  /** Inner content that contains `<BeamNode>` children. */
  children: React.ReactNode;
  /** Default beam color when a connection doesn't override. */
  color?: string;
  /** Width of the SVG stroke in px. */
  strokeWidth?: number;
  /** Soft glow filter intensity. */
  glow?: number;
  className?: string;
}

interface BeamContextValue {
  register(id: string, el: HTMLElement | null): void;
}
const BeamCtx = React.createContext<BeamContextValue | null>(null);

/**
 * BeamNode
 *
 * Mark any element as a beam endpoint. The wrapper itself is a `display:
 * contents` ghost so it doesn't disturb your layout — we read the bounding
 * box from a child ref attached via a fragment-safe wrapper.
 */
export function BeamNode({
  id,
  children,
  className,
}: {
  id: string;
  children: React.ReactNode;
  className?: string;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const ctx = React.useContext(BeamCtx);

  React.useEffect(() => {
    if (!ctx) return;
    ctx.register(id, ref.current);
    return () => ctx.register(id, null);
  }, [ctx, id]);

  return (
    <div ref={ref} data-beam-node={id} className={cn("relative", className)}>
      {children}
    </div>
  );
}

/**
 * InteractiveBeamConnections
 *
 * SVG beams that auto-route between any two `<BeamNode>` children.
 *
 * Mechanics:
 *  - A `ResizeObserver` on the wrapper + the document scroll keeps the
 *    cached node rects fresh.
 *  - Cubic bezier path is generated per connection; control points bow
 *    along the dominant axis to keep curves graceful.
 *  - The "shooting" pulse is `stroke-dashoffset` on a dashed copy of the
 *    path — never animates the path string itself.
 *  - On pulse arrival, the target card gets a tiny `useSpring` scale bump
 *    via the `data-beam-bump` attribute so it physically receives the packet.
 */
export function InteractiveBeamConnections({
  connections,
  children,
  // Sky default — beams are "data flowing between nodes", and the universal
  // colour for that is sky/cyan (AWS architecture diagrams, Cloudflare,
  // network-traffic visualisations). Red beams read as "alerts firing
  // between services". Pass `color` to override per-instance, or wrap in
  // a `data-theme="..."` block to retone via the palette system.
  color = "#0ea5e9",
  strokeWidth = 1.6,
  glow = 6,
  className,
}: InteractiveBeamConnectionsProps) {
  const wrapperRef = React.useRef<HTMLDivElement>(null);
  const nodesRef = React.useRef<Map<string, HTMLElement>>(new Map());
  const roRef = React.useRef<ResizeObserver | null>(null);
  const [tick, setTick] = React.useState(0);
  const [size, setSize] = React.useState({ w: 0, h: 0 });

  const recompute = React.useCallback(() => {
    setTick((t) => t + 1);
  }, []);

  /* ── Register / unregister nodes (also wires them into the live ResizeObserver) ── */
  const register = React.useCallback(
    (id: string, el: HTMLElement | null) => {
      const ro = roRef.current;
      const prev = nodesRef.current.get(id);
      if (prev && ro) ro.unobserve(prev);
      if (!el) {
        nodesRef.current.delete(id);
      } else {
        nodesRef.current.set(id, el);
        if (ro) ro.observe(el);
      }
      // Defer recompute to a microtask so registration during render commit
      // doesn't synchronously trigger a parent setState (which would loop
      // through child effects). The ResizeObserver also keeps coords fresh.
      queueMicrotask(recompute);
    },
    [recompute]
  );

  // Stable context value — without useMemo, every parent render produces a new
  // object, which would re-run every <BeamNode>'s effect (deps include ctx)
  // and create an infinite register → setTick → render loop.
  const ctxValue = React.useMemo<BeamContextValue>(() => ({ register }), [register]);

  /* ── Track wrapper + node sizes. Scroll is intentionally NOT observed: beam coords
     are wrapper-relative so they don't change when the page scrolls. ── */
  React.useEffect(() => {
    const wrap = wrapperRef.current;
    if (!wrap) return;
    const ro = new ResizeObserver(() => {
      const r = wrap.getBoundingClientRect();
      setSize((prev) =>
        prev.w === r.width && prev.h === r.height ? prev : { w: r.width, h: r.height }
      );
      recompute();
    });
    roRef.current = ro;
    ro.observe(wrap);
    for (const el of nodesRef.current.values()) ro.observe(el);
    return () => {
      ro.disconnect();
      roRef.current = null;
    };
  }, [recompute]);

  /* ── Compute beam paths against the wrapper's coord system ── */
  const beams = React.useMemo(() => {
    const wrap = wrapperRef.current;
    if (!wrap) return [];
    const wr = wrap.getBoundingClientRect();
    const result: Array<{
      id: string;
      d: string;
      from: string;
      to: string;
      color: string;
      duration: number;
      delay: number;
      interval: number;
    }> = [];
    connections.forEach((c, i) => {
      const a = nodesRef.current.get(c.from);
      const b = nodesRef.current.get(c.to);
      if (!a || !b) return;
      const ar = a.getBoundingClientRect();
      const br = b.getBoundingClientRect();
      const x1 = ar.left + ar.width / 2 - wr.left;
      const y1 = ar.top + ar.height / 2 - wr.top;
      const x2 = br.left + br.width / 2 - wr.left;
      const y2 = br.top + br.height / 2 - wr.top;

      const dx = x2 - x1;
      const dy = y2 - y1;
      const horizontal = Math.abs(dx) >= Math.abs(dy);
      const k = c.curvature ?? 0.45;
      const cx1 = horizontal ? x1 + dx * 0.5 : x1;
      const cy1 = horizontal ? y1 - Math.abs(dx) * k * Math.sign(dy || 1) * 0.3 : y1 + dy * 0.5;
      const cx2 = horizontal ? x2 - dx * 0.5 : x2;
      const cy2 = horizontal
        ? y2 - Math.abs(dx) * k * Math.sign(dy || 1) * 0.3
        : y2 - dy * 0.5;

      const ctrl1x = horizontal ? x1 + dx * 0.35 : x1 + dx * k;
      const ctrl1y = horizontal ? y1 + dy * 0.05 : y1 + dy * 0.35;
      const ctrl2x = horizontal ? x2 - dx * 0.35 : x2 - dx * k;
      const ctrl2y = horizontal ? y2 - dy * 0.05 : y2 - dy * 0.35;

      // Use bowed control points on the perpendicular axis for a graceful arc.
      const usedC1x = horizontal ? ctrl1x : cx1;
      const usedC1y = horizontal ? ctrl1y - 28 : ctrl1y;
      const usedC2x = horizontal ? ctrl2x : cx2;
      const usedC2y = horizontal ? ctrl2y - 28 : ctrl2y;

      const d = `M ${x1} ${y1} C ${usedC1x} ${usedC1y}, ${usedC2x} ${usedC2y}, ${x2} ${y2}`;

      result.push({
        id: c.id ?? `${c.from}->${c.to}-${i}`,
        d,
        from: c.from,
        to: c.to,
        color: c.color ?? color,
        duration: c.duration ?? 1500,
        delay: c.delay ?? i * 350,
        interval: c.interval ?? 3200,
      });
    });
    return result;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [connections, color, size.w, size.h, tick]);

  return (
    <BeamCtx.Provider value={ctxValue}>
      <div ref={wrapperRef} className={cn("relative w-full", className)}>
        {/* SVG layer behind content */}
        <svg
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full"
          width={size.w || "100%"}
          height={size.h || "100%"}
          viewBox={`0 0 ${size.w || 1} ${size.h || 1}`}
          preserveAspectRatio="none"
        >
          <defs>
            <filter id="wensity-beam-glow" x="-30%" y="-30%" width="160%" height="160%">
              <feGaussianBlur stdDeviation={glow} result="b" />
              <feMerge>
                <feMergeNode in="b" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {beams.map((b) => (
            <Beam
              key={b.id}
              path={b.d}
              color={b.color}
              strokeWidth={strokeWidth}
              duration={b.duration}
              delay={b.delay}
              interval={b.interval}
              onArrive={() => bumpNode(nodesRef.current.get(b.to))}
            />
          ))}
        </svg>

        {/* Content */}
        <div className="relative">{children}</div>
      </div>
    </BeamCtx.Provider>
  );
}

/* ─────────────────────────────────────────────────────────────── */

function Beam({
  path,
  color,
  strokeWidth,
  duration,
  delay,
  interval,
  onArrive,
}: {
  path: string;
  color: string;
  strokeWidth: number;
  duration: number;
  delay: number;
  interval: number;
  onArrive: () => void;
}) {
  const pathRef = React.useRef<SVGPathElement>(null);
  const [length, setLength] = React.useState(0);

  React.useEffect(() => {
    const el = pathRef.current;
    if (!el) return;
    setLength(el.getTotalLength());
  }, [path]);

  const offset = useMotionValue(length || 1);

  React.useEffect(() => {
    if (!length) return;
    let mounted = true;
    let timeoutId: number | undefined;

    const cycle = () => {
      offset.set(length);
      const ctrl = animate(offset, -length * 0.05, {
        duration: duration / 1000,
        ease: [0.65, 0, 0.35, 1],
        onComplete: () => {
          if (!mounted) return;
          onArrive();
          timeoutId = window.setTimeout(cycle, interval);
        },
      });
      return ctrl;
    };

    timeoutId = window.setTimeout(cycle, delay);
    return () => {
      mounted = false;
      if (timeoutId) window.clearTimeout(timeoutId);
    };
  }, [length, duration, delay, interval, offset, onArrive]);

  if (!path) return null;

  // Dash length is a small slice of the total — that's the visible beam.
  const dashSlice = Math.max(40, length * 0.18);
  const dashGap = Math.max(length, 200);

  return (
    <g>
      {/* Static rail (very faint) */}
      <path
        ref={pathRef}
        d={path}
        fill="none"
        stroke={color}
        strokeOpacity={0.15}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      />
      {/* Glowing pulse */}
      <motion.path
        d={path}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth + 0.6}
        strokeLinecap="round"
        filter="url(#wensity-beam-glow)"
        style={{
          strokeDasharray: `${dashSlice} ${dashGap}`,
          strokeDashoffset: offset,
        }}
      />
    </g>
  );
}

function bumpNode(el: HTMLElement | undefined) {
  if (!el) return;
  // Drive a tiny scale spring via Web Animations API — independent of React render.
  el.animate(
    [
      { transform: "scale(1)" },
      { transform: "scale(1.045)", offset: 0.4 },
      { transform: "scale(1)" },
    ],
    {
      duration: 460,
      easing: "cubic-bezier(.2,.9,.3,1.2)",
    }
  );
}
